engine.definedTermsScan:
function definedTermsScan(input, providers) {
  var paras = (input && input.paragraphs) || [];

  // ── shared bits ──────────────────────────────────────────────────────
  var TRIGGER = "(?:means|shall\\s+mean|shall\\s+have\\s+the\\s+meaning|has\\s+the\\s+meaning" +
    "|shall\\s+refer\\s+to|refers\\s+to|shall\\s+be\\s+deemed\\s+to\\s+mean)";
  var RE_TRIGGER = new RegExp("\\b" + TRIGGER + "\\b", "i");
  // Lowercase words allowed INSIDE a term — "Statement of Work", "Terms and
  // Conditions". First and last word must still be capitalised.
  var CONNECTORS = { of: 1, and: 1, or: 1, the: 1, a: 1, an: 1, to: 1, for: 1, in: 1, on: 1 };
  // Capitalised but never a defined term on their own.
  var STOPWORDS = {
    January: 1, February: 1, March: 1, April: 1, May: 1, June: 1, July: 1,
    August: 1, September: 1, October: 1, November: 1, December: 1,
    Monday: 1, Tuesday: 1, Wednesday: 1, Thursday: 1, Friday: 1, Saturday: 1, Sunday: 1,
    The: 1, This: 1, That: 1, These: 1, Those: 1, Each: 1, Any: 1, All: 1, If: 1,
    Section: 1, Article: 1, Exhibit: 1, Schedule: 1, Annex: 1, Appendix: 1,
    Company: 0, // deliberately NOT excluded — often a real defined term
  };
  function _rx(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
  // Singular/plural variants of a term. A contract defines "Affiliate" once
  // and then writes "Affiliates" 24 times; counting only the exact string
  // undercounts every term and reports one used solely in the plural as
  // "defined but never used". Only the LAST word inflects — "Service
  // Exhibit" → "Service Exhibits", never "Services Exhibit".
  function _forms(term) {
    var parts = String(term).split(/\s+/);
    var last = parts[parts.length - 1];
    var out = [term];
    function push(v) {
      if (!v || v === last) return;
      var full = parts.slice(0, -1).concat(v).join(" ");
      if (out.indexOf(full) === -1) out.push(full);
    }
    if (/[^aeiouAEIOU]y$/.test(last)) push(last.replace(/y$/, "ies"));
    else if (/(s|x|z|ch|sh)$/i.test(last)) push(last + "es");
    else push(last + "s");
    if (/ies$/i.test(last)) push(last.replace(/ies$/, "y"));
    else if (/(s|x|z|ch|sh)es$/i.test(last)) push(last.replace(/es$/, ""));
    else if (/s$/i.test(last)) push(last.replace(/s$/, ""));
    return out;
  }
  function _clean(s) {
    return String(s == null ? "" : s)
      .replace(/^[\s"“”'‘’(\[]+/, "").replace(/[\s"“”'‘’)\].,;:]+$/, "").trim();
  }
  // A term must look like a term: 2-60 chars, starts capitalised, every word
  // either capitalised or a connector, and not a bare stopword.
  function _plausible(t) {
    t = _clean(t);
    if (t.length < 2 || t.length > 60) return null;
    if (!/^[A-Z“"]/.test(t)) return null;
    if (/[.;:]$/.test(t)) return null;
    var words = t.split(/\s+/);
    if (words.length > 7) return null;
    if (words.length === 1) {
      // Check the singular too, or "Exhibits" walks past a stoplist that
      // only knows "Exhibit".
      var sf = _forms(t);
      for (var si = 0; si < sf.length; si++) if (STOPWORDS[sf[si]] === 1) return null;
    }
    for (var i = 0; i < words.length; i++) {
      var w = words[i].replace(/[^A-Za-z0-9'’\-]/g, "");
      if (!w) continue;
      var isCap = /^[A-Z0-9]/.test(w);
      var isConn = CONNECTORS[w.toLowerCase()] === 1;
      if (!isCap && !isConn) return null;
      if (i === 0 && !isCap) return null;
      if (i === words.length - 1 && !isCap) return null;
    }
    return t;
  }

  // Walk backwards from `end` over capitalised words to find where an
  // UNQUOTED term starts. This is the case quotes solve for free and plain
  // text otherwise cannot — the reason formatting matters at all.
  function _walkBackCap(text, end) {
    var left = text.slice(0, end).replace(/\s+$/, "");
    var words = left.split(/\s+/);
    var take = [];
    for (var i = words.length - 1; i >= 0 && take.length < 7; i--) {
      var w = words[i];
      var bare = w.replace(/[^A-Za-z0-9'’\-]/g, "");
      if (!bare) break;
      if (/^[A-Z0-9]/.test(bare)) { take.unshift(w); continue; }
      if (CONNECTORS[bare.toLowerCase()] === 1 && take.length) { take.unshift(w); continue; }
      break;
    }
    // Drop leading connectors — "the Receiving Party" → "Receiving Party".
    while (take.length && CONNECTORS[take[0].replace(/[^A-Za-z]/g, "").toLowerCase()] === 1) take.shift();
    return take.length ? _plausible(take.join(" ")) : null;
  }

  // Formatted runs that sit immediately before `idx`, merged. Gives exact
  // boundaries for "**Confidential Information** means …".
  function _formattedBefore(p, idx) {
    var runs = (p && p.runs) || [];
    if (!runs.length) return null;
    var at = 0, acc = "", fmt = null;
    for (var i = 0; i < runs.length; i++) {
      var r = runs[i], len = String(r.text || "").length;
      var isFmt = !!(r.bold || r.italic || r.underline);
      var endsAt = at + len;
      // The run must END within a few characters of the trigger (allowing a
      // space, a colon, a quote) — not merely appear somewhere earlier.
      if (isFmt && endsAt <= idx && idx - endsAt <= 3) {
        acc += r.text;
        fmt = { bold: !!r.bold, italic: !!r.italic, underline: !!r.underline };
      } else if (isFmt && endsAt <= idx) {
        acc = ""; fmt = null;                    // too far back — start over
      } else if (!isFmt && endsAt <= idx && String(r.text || "").trim()) {
        acc = ""; fmt = null;                    // plain text broke the span
      }
      at = endsAt;
    }
    var t = _plausible(acc);
    return t ? { term: t, formatting: fmt } : null;
  }

  function _trim600(s) {
    var out = String(s || "").trim();
    if (out.length > 600) out = out.slice(0, 597).replace(/\s+\S*$/, "") + "…";
    return out;
  }
  // The definition body: from after the trigger to the end of the sentence.
  function _definitionAfter(text, from) {
    var rest = text.slice(from).replace(/^[\s:,]+/, "");
    var m = /[.;]\s+(?=[A-Z(])/.exec(rest);
    return _trim600(m ? rest.slice(0, m.index + 1) : rest);
  }
  // For a parenthetical — (the "Breaching Party") — the definition is the
  // SENTENCE the parenthetical sits in. Taking the paragraph from character
  // zero returned the bold section heading ("Material Breach.") instead.
  function _definitionAround(text, idx) {
    var left = text.slice(0, idx);
    var start = 0, sm, sre = /[.;]\s+(?=[A-Z(“"])/g;
    while ((sm = sre.exec(left)) !== null) start = sm.index + sm[0].length;
    var rest = text.slice(start);
    var em = /[.;]\s+(?=[A-Z(])/.exec(rest.slice(idx - start));
    return _trim600(em ? rest.slice(0, (idx - start) + em.index + 1) : rest);
  }

  // The exact string Locate should look for INSIDE the definition paragraph.
  // The bare term is not enough: a preamble reads "XYZ Company, a Delaware
  // corporation (the “Company”)", so searching for "Company" lands on the
  // company NAME, not on the definition a few words later.
  //
  // `after` says which side of `hint` the term sits — the quoted rules match
  // at the term, the trigger rules match after it.
  function _needleAt(text, term, hint, after) {
    if (!text || !term) return null;
    var at = after
      ? text.indexOf(term, Math.max(0, (hint || 0) - 2))
      : text.lastIndexOf(term, hint == null ? text.length : hint);
    if (at === -1) at = text.indexOf(term);
    if (at === -1) return null;
    var s = at, e = at + term.length;
    // Quoted definitions are self-delimiting — “Company” appears once even
    // when the bare word appears three times. US style puts the sentence
    // punctuation INSIDE the quote ("a “Party.”"), so step over it before
    // looking for the closing mark.
    var pre = s > 0 ? text.charAt(s - 1) : "";
    var e2 = e;
    while (e2 < text.length && e2 - e < 2 && /[.,;:!?]/.test(text.charAt(e2))) e2++;
    var post = text.charAt(e2);
    if ((pre === '"' || pre === "“") && (post === '"' || post === "”")) {
      return text.slice(s - 1, e2 + 1);
    }
    // Unquoted: carry the definitional verb along, so "Company means" is
    // distinct from the company name.
    var tail = text.slice(e, e + 60);
    var tm = new RegExp("^[\\s:,]{0,45}?" + TRIGGER, "i").exec(tail);
    if (tm) return text.slice(s, e + tm[0].length);
    return text.slice(s, e);
  }

  // ── the document ─────────────────────────────────────────────────────
  var texts = paras.map(function (p) { return String((p && p.text) || ""); });
  var fullText = texts.join("\n");

  function _isHeadingLike(t) {
    var s = String(t || "").trim();
    if (!s || s.length > 90) return false;
    if (/[.;]$/.test(s) && !/^\s*(article|section)\b/i.test(s)) return false;
    return /^(article|section)?\s*[\dIVXivx]*[.)]?\s*[A-Z]/.test(s) && s.split(/\s+/).length <= 12;
  }

  // ── Pass 1: the Definitions article ──────────────────────────────────
  // Highest precision available: inside that region every item's leading
  // phrase is a defined term, quoted or not, formatted or not.
  var RE_DEFHEAD = /^\s*(?:article|section)?\s*[\dIVXivx]*[.)]?\s*(?:certain\s+)?(?:defined\s+terms?|definitions?)\s*[.:]?\s*$/i;
  // A definition ITEM: opens with a quote, carries a trigger, or points
  // elsewhere ("is defined in Section 9.2.1").
  var RE_XREF = /\b(?:is|are)\s+defined\s+in\b|\bhas\s+the\s+meaning\s+(?:set\s+forth|given|ascribed)\b/i;
  function _isDefItem(txt) {
    var t = String(txt || "").trim();
    if (!t) return false;
    return /^["“]/.test(t) || RE_TRIGGER.test(t) || RE_XREF.test(t) ||
      /^\s*(?:\(?[a-z0-9ivx]{1,4}[.)]\s*)?[^:\n]{2,60}:\s+\S/i.test(t);
  }
  // End the region on CONTENT, not on a heading pattern. This document's
  // headings are bare ALL-CAPS ("DEFINITIONS", "GENERAL OBLIGATIONS") with no
  // ARTICLE/SECTION prefix, so matching the next heading never fired and the
  // region swallowed the whole document.
  var defRegion = null;
  for (var i = 0; i < texts.length; i++) {
    if (!RE_DEFHEAD.test(texts[i])) continue;
    var end = texts.length, miss = 0, firstMiss = -1;
    for (var j = i + 1; j < texts.length; j++) {
      if (_isDefItem(texts[j])) { miss = 0; firstMiss = -1; continue; }
      if (!String(texts[j]).trim()) continue;              // blank spacer
      if (firstMiss === -1) firstMiss = j;
      miss++;
      // A heading ends it at once; otherwise tolerate one stray paragraph (a
      // definition running onto a second paragraph) before giving up.
      if (_isHeadingLike(texts[j]) || miss >= 2) { end = firstMiss; break; }
    }
    defRegion = { start: i + 1, end: end };
    break;
  }
  // A "definitions section" covering half the document is a failed end
  // detection, not a definitions section. Trusting it promoted every
  // exhibit table cell ("Attn: CEO", "Quote: QS-26-1221-2") into a term.
  var defRegionRejected = null;
  if (defRegion && (defRegion.end - defRegion.start) > texts.length * 0.5) {
    defRegionRejected = defRegion;
    defRegion = null;
  }

  var found = {};   // normalised term → record
  function _record(term, def, paraIdx, via, formatting, confidence, hint, after) {
    term = _plausible(term);
    if (!term) return;
    var key = term.toLowerCase();
    var inSection = !!(defRegion && paraIdx >= defRegion.start && paraIdx < defRegion.end);
    var site = {
      paraIdx: paraIdx, via: via, inSection: inSection,
      anchor: (paras[paraIdx] && paras[paraIdx].anchor) || null,
      needle: _needleAt(texts[paraIdx], term, hint, after) || term,
      confidence: confidence,
    };
    var prior = found[key];
    if (prior) {
      // Two rules can land on the same definition. Count it once, or a term
      // caught by both the quoted and the designation rule reads as a
      // duplicate definition it is not.
      var dup = prior.sites.some(function (s) {
        return s.paraIdx === paraIdx && s.needle === site.needle;
      });
      if (dup) return;
      prior.sites.push(site);
      // A cross-reference ("defined in Section 9.2.1") is a POINTER, not a
      // second definition — counting it would report half the glossary as
      // "defined twice".
      if (via !== "xref") prior.definitionCount++;
      // Keep the strongest evidence, but remember there were several sites.
      if (confidence > prior.confidence) {
        prior.definition = def || prior.definition;
        prior.anchor = (paras[paraIdx] && paras[paraIdx].anchor) || prior.anchor;
        prior.locateNeedle = _needleAt(texts[paraIdx], term, hint, after) || prior.locateNeedle;
        prior.via = via; prior.formatting = formatting || prior.formatting;
        prior.confidence = confidence; prior.paraIdx = paraIdx;
      }
      return;
    }
    found[key] = {
      term: term, definition: def || "", paraIdx: paraIdx,
      // Kernel index anchor for the paragraph this definition sits in.
      // Locate jumps to it directly — a body-wide search lands on whichever
      // occurrence comes first, which is nearly always a heading, not the
      // definition.
      anchor: (paras[paraIdx] && paras[paraIdx].anchor) || null,
      locateNeedle: _needleAt(texts[paraIdx], term, hint, after) || term,
      via: via,
      formatting: formatting || null, confidence: confidence,
      definitionCount: (via === "xref" ? 0 : 1), uses: 0,
      sites: [site],
    };
  }

  // A short lowercase appositive may sit between the term and the trigger:
  //   "Confidential Information" AS IT APPLIES TO A PARTY, means: …
  // Without this the trigger match failed, the bare-capitalised fallback ran
  // instead, and it walked back from `means` to capture "Party" — so the real
  // term went missing AND another term inherited its definition.
  // The gap must start lowercase and carry no quote or sentence break, which
  // is what an appositive looks like and what a new clause does not.
  var RE_QUOTED_TRIGGER = new RegExp(
    '["“]([^"“”\\n]{2,60})["”]\\s*\\)?\\s*(?:,?\\s+[a-z][^"“”.;:\\n]{0,40}?)?,?\\s*:?\\s*' +
    TRIGGER, "gi");
  // A parenthetical routinely defines SEVERAL terms at once:
  //   (each a "Party" and together the "Parties")
  // Matching one quoted string then demanding ")" missed every one of those,
  // which is why "Parties" came back as an undefined term. Match the whole
  // parenthetical, then take every quoted string inside it.
  var RE_PAREN = /\(([^()\n]{0,200}?["“][^"“”\n]{2,60}["”][^()\n]{0,200}?)\)/g;
  var RE_INNER_Q = /["“]([^"“”\n]{2,60})["”]/g;
  var RE_PAREN_LEAD = /^\s*(?:the|each(?:,?\s+an?)?|an?|collectively,?(?:\s+the)?|individually,?(?:\s+an?)?|together,?(?:\s+the)?|and\s+together,?(?:\s+the)?|hereinafter(?:\s+referred\s+to\s+as)?,?(?:\s+the)?)?\s*["“]/i;
  // "X" is defined in Section 9.2.1 — a POINTER, not a definition.
  var RE_XREF_SHAPE =
    /["“]([^"“”\n]{2,60})["”](?:\s+and\s+["“]([^"“”\n]{2,60})["”])?\s+(?:is|are)\s+defined\s+in\b/gi;
  var RE_DESIGNATE = new RegExp(
    '(?:referred\\s+to(?:\\s+herein)?(?:\\s+(?:collectively|individually|together|separately))?\\s+as' +
    '|(?:collectively|individually)\\s+as|known\\s+as|designated\\s+as|defined\\s+as)' +
    '\\s*,?\\s*(?:the|an?)?\\s*["“]([^"“”\\n]{2,60})["”]', "gi");

  paras.forEach(function (p, pi) {
    var text = texts[pi];
    if (!text.trim()) return;
    var inDefSection = !!(defRegion && pi >= defRegion.start && pi < defRegion.end);
    var m;

    // (a) quoted + trigger — "Confidential Information" means …
    RE_QUOTED_TRIGGER.lastIndex = 0;
    while ((m = RE_QUOTED_TRIGGER.exec(text)) !== null) {
      _record(m[1], _definitionAfter(text, m.index + m[0].length), pi,
        inDefSection ? "section" : "quoted", null, inDefSection ? 0.97 : 0.92,
        m.index, true);
    }

    // (b) parenthetical — (the "Disclosing Party"), (each a "Party" and
    //     together the "Parties")
    RE_PAREN.lastIndex = 0;
    while ((m = RE_PAREN.exec(text)) !== null) {
      // Only a DEFINING parenthetical — one that opens with the/each/a/
      // collectively/together — not an ordinary quotation inside brackets.
      if (!RE_PAREN_LEAD.test(m[1])) continue;
      var inner, qs = [];
      RE_INNER_Q.lastIndex = 0;
      while ((inner = RE_INNER_Q.exec(m[1])) !== null) qs.push(inner[1]);
      var around = _definitionAround(text, m.index);
      for (var qi = 0; qi < qs.length; qi++) {
        _record(qs[qi], around, pi, "quoted", null, 0.9, m.index, true);
      }
    }

    // (c) formatted + trigger — **Confidential Information** means …
    // (d) bare capitalised + trigger — Confidential Information means …
    // EVERY trigger in the paragraph, not just the first. A body paragraph
    // routinely carries two definitions ("Deliverables means the outputs and
    // Materials means the items supplied"), and stopping at the first one
    // hid the second — which is how a term defined in the definitions section
    // AND again in the body was reported as section-only instead of both.
    var quotedEnds = [];
    RE_QUOTED_TRIGGER.lastIndex = 0;
    var q;
    while ((q = RE_QUOTED_TRIGGER.exec(text)) !== null) quotedEnds.push(q.index + q[0].length);

    var reTrigAll = new RegExp("\\b" + TRIGGER + "\\b", "gi");
    var tm;
    while ((tm = reTrigAll.exec(text)) !== null) {
      var at = tm.index;
      var end = at + tm[0].length;
      // Rule (a) already recorded this one from its quoted form.
      var already = quotedEnds.some(function (e) { return Math.abs(e - end) < 4; });
      if (already) continue;
      var fb = _formattedBefore(p, at);
      if (fb) {
        _record(fb.term, _definitionAfter(text, end), pi,
          inDefSection ? "section" : "formatted", fb.formatting,
          inDefSection ? 0.96 : 0.88, at, false);
      } else {
        var bare = _walkBackCap(text, at);
        if (bare) {
          _record(bare, _definitionAfter(text, end), pi,
            inDefSection ? "section" : "inferred", null,
            inDefSection ? 0.9 : 0.62, at, false);
        }
      }
    }

    // (g) A cross-reference entry. It is not a definition, but it proves the
    // term is LISTED in the definitions section while the wording lives
    // elsewhere — which is exactly the "listed here, defined there" case.
    // Confidence is low so a real definition in the body always wins display.
    RE_XREF_SHAPE.lastIndex = 0;
    var xm;
    while ((xm = RE_XREF_SHAPE.exec(text)) !== null) {
      _record(xm[1], "", pi, "xref", null, 0.45, xm.index, true);
      if (xm[2]) _record(xm[2], "", pi, "xref", null, 0.45, xm.index, true);
    }

    // (f) designation without parentheses or a trigger verb:
    //   Colgate and Provider are referred to herein collectively as the
    //   "Parties" and individually as a "Party."
    // Extremely common in preambles, and it is how this shape hid: no
    // brackets to match, no "means" to anchor on.
    RE_DESIGNATE.lastIndex = 0;
    var dm;
    while ((dm = RE_DESIGNATE.exec(text)) !== null) {
      _record(dm[1], _definitionAround(text, dm.index), pi, "quoted", null, 0.9,
        dm.index, true);
    }

    // (e) definitions-section list item with a colon — "Affiliate: any entity…"
    if (inDefSection && !tm) {
      var cm = /^\s*(?:\(?[a-z0-9ivx]{1,4}[.)]\s*)?([^:\n]{2,60}):\s+(\S)/i.exec(text);
      if (cm) {
        var t2 = _plausible(cm[1]);
        if (t2) {
          _record(t2, _definitionAfter(text, text.indexOf(":") + 1), pi, "section", null, 0.9,
            0, true);
        }
      }
    }
  });

  // ── Usage counts ─────────────────────────────────────────────────────
  // Word-boundary AND case-sensitive, then subtract occurrences that are
  // really part of a LONGER defined term — a bare indexOf counts the "Term"
  // inside "Renewal Term", which is how "defined but never used" goes wrong
  // in both directions.
  var terms = Object.keys(found).map(function (k) { return found[k]; });
  var byLen = terms.slice().sort(function (a, b) { return b.term.length - a.term.length; });
  function _countWhole(hay, needle) {
    var re = new RegExp("(^|[^A-Za-z0-9])" + _rx(needle) + "(?![A-Za-z0-9])", "g");
    var n = 0; while (re.exec(hay) !== null) n++;
    return n;
  }
  terms.forEach(function (rec) {
    // A variant that is itself separately defined belongs to THAT record —
    // this agreement defines both "Party" and "Parties", so neither may
    // absorb the other's uses.
    var forms = _forms(rec.term).filter(function (f) {
      return f === rec.term || !found[f.toLowerCase()];
    });
    var total = 0, perForm = {};
    forms.forEach(function (f) {
      var n = _countWhole(fullText, f);
      perForm[f] = n; total += n;
    });
    byLen.forEach(function (other) {
      if (other === rec) return;
      if (other.term.length <= rec.term.length) return;
      if (other.term.indexOf(rec.term) === -1) return;
      _forms(other.term).forEach(function (of) { total -= _countWhole(fullText, of); });
    });
    rec.forms = forms;
    rec.usesByForm = perForm;
    rec.uses = Math.max(0, total - rec.definitionCount);
    // Reuse is formatting-independent corroboration; an inferred term used
    // repeatedly is almost certainly real.
    if (rec.via === "inferred" && rec.uses >= 2) rec.confidence = Math.min(0.9, rec.confidence + 0.2);
  });

  // ── Used but never defined ───────────────────────────────────────────
  // Capitalised phrase appearing MID-sentence (a lowercase word before it)
  // two or more times, with no definition. No head-noun list: reuse plus
  // mid-sentence capitalisation is the signal.
  var candidates = {};
  // "of" joins a phrase — otherwise "Statement of Work" was harvested as two
  // separate candidates, "Statement" and "Work", neither of which means
  // anything. "and"/"or" are deliberately NOT joiners: they would glue
  // "Colgate and Provider" into one invented term.
  // A whole lowercase WORD must precede, not merely a lowercase character:
  // "[a-z]\s+York" matched the "w" of "New", so every proper noun also
  // yielded its own tail as a candidate ("York" out of "New York").
  var RE_CAND = new RegExp(
    "(?:^|[\\s(\\[])([a-z][A-Za-z0-9'’\\-]*),?;?\\s+" +
    "([A-Z][A-Za-z0-9'’\\-]+(?:\\s+(?:of|for)\\s+[A-Z][A-Za-z0-9'’\\-]+|\\s+[A-Z][A-Za-z0-9'’\\-]+){0,3})",
    "g");
  // Noise suppressors. These are a STOPLIST, not the allowlist I argued
  // against: a wrong entry here costs one advisory line, whereas the
  // head-noun allowlist gated DETECTION and silently lost real terms.
  var GEO_HEAD = /^(County|State|City|Town|Province|Commonwealth|Republic|Street|Avenue|Road|Boulevard|Suite|Floor|District)$/;
