          text: _decode(text),
          bold: _on(rPr, "b"), italic: _on(rPr, "i"), underline: _on(rPr, "u"),
        });
      }
      var merged = [];
      runs.forEach(function (r) {
        var last = merged[merged.length - 1];
        if (last && last.bold === r.bold && last.italic === r.italic &&
            last.underline === r.underline) { last.text += r.text; }
        else { merged.push({ text: r.text, bold: r.bold, italic: r.italic, underline: r.underline }); }
      });
      out.push(merged);
    }
    return out;
  }
  // ─── [/OOXML-RUNS] ───────────────────────────────────────────────────

  // Two INDEPENDENT host calls. Batching them means one failing rejects the
  // other, and the text pass alone still finds every quoted definition — so a
  // formatting failure must degrade, not wipe out the scan.
  // readStructuralMap bookmarks every paragraph as ELI_IDX_<i> and hands back
  // the rows. Using it instead of a plain paragraphs read is what makes
  // Locate exact: each definition carries the anchor of the paragraph it sits
  // in, so navigating is a bookmark lookup rather than a body-wide search for
  // the term — which finds whichever occurrence comes first (a heading, the
  // table of contents) rather than the definition, and fails outright on
  // terms carrying curly apostrophes or Word's own special characters.
  //
  // It is the SHARED index (default ELI_IDX_ prefix), session-cached with a
  // fast path on warm re-runs, so this costs nothing the rest of ELI isn't
  // already paying.
  function _readText() {
    return eli.host.readStructuralMap().then(function (map) {
      return (map.paragraphs || []).map(function (row, i) {
        return {
          id: row.anchor || ("p" + i),
          text: String(row.text || ""),
          runs: null,
          anchor: row.anchor || null,
          idx: (row.idx == null ? i : row.idx),
          section: row.belongsTo || null,
        };
      });
    });
  }
  function _readRuns() {
    return eli.host.runRaw("defined_terms:ooxml", function (context) {
      var ooxml = context.document.body.getOoxml();
      return context.sync().then(function () {
        return _paragraphRuns(_documentXml(ooxml.value));
      });
    });
  }

  // Pair OOXML runs to paragraphs by matching their text. Counts differ —
  // OOXML includes paragraphs inside table cells and text boxes — so runs
  // attach only where the text matches, and the misses are REPORTED rather
  // than silently mis-paired. Returns {aligned, unmatched}; mutates p.runs.
  function _attachRuns(textParas, runsByPara) {
    if (!runsByPara) return { aligned: 0, unmatched: 0 };
    var aligned = 0, unmatched = 0, used = {};
    var flat = function (s) { return String(s || "").replace(/\s+/g, ""); };
    textParas.forEach(function (p, i) {
      var cand = runsByPara[i];
      var joined = cand ? cand.map(function (r) { return r.text; }).join("") : null;
      if (joined != null && flat(joined) === flat(p.text)) {
        p.runs = cand; used[i] = 1; aligned++;
        return;
      }
      for (var j = 0; j < runsByPara.length; j++) {
        if (used[j]) continue;
        var jt = runsByPara[j].map(function (r) { return r.text; }).join("");
        if (jt && flat(jt) === flat(p.text)) {
          p.runs = runsByPara[j]; used[j] = 1; aligned++; return;
        }
      }
      unmatched++;
    });
    return { aligned: aligned, unmatched: unmatched };
  }

  function _scan() {
    if (_busy) { if (typeof showToast === "function") showToast("Already scanning.", "info"); return; }
    _busy = true;
    if (typeof showToast === "function") showToast("Reading document…", "info");
    var textParas = null, runErr = null;
    return _readText()
      .then(function (tp) {
        textParas = tp;
        return _readRuns().catch(function (e) { runErr = e; return null; });
      })
      .then(function (runsByPara) {
        var a = _attachRuns(textParas, runsByPara);
        var aligned = a.aligned, skewed = a.unmatched;
        var res = definedTermsScan({
          paragraphs: textParas,
          toolVersion: (bundle && bundle.releasedAt) || "unknown",
        }, { host: eli.host });
        res._meta.formattingRead = {
          ok: !runErr, aligned: aligned, unmatched: skewed,
          error: runErr ? ((runErr && runErr.message) || "unknown") : null,
        };
        if (eli.log && typeof eli.log.event === "function") {
          eli.log.event("tool", "defined_terms_scan", {
            paragraphs: textParas.length, terms: res.items.length,
            aligned: aligned, unmatched: skewed, formattingOk: !runErr,
          });
        }
        if (runErr && typeof showToast === "function") {
          showToast("Formatting could not be read (" + res._meta.formattingRead.error +
            ") — quoted definitions only.", "warn");
        }
        _render(res);
        if (eli.stats && typeof eli.stats.record === "function") {
          eli.stats.record("appOpenedDefinedTerms", 1);
        }
      })
      .catch(function (err) {
        if (typeof showToast === "function") {
          showToast("Defined-terms scan failed: " + ((err && err.message) || "unknown"), "err");
        }
      })
      .then(function () { _busy = false; });
  }

  function _render(res) {
    renderDefinedTerms({
      result: res,
      onRescan: function () { _scan(); },
      // Bookmark first, then narrow INSIDE that paragraph. The narrowing
      // search is scoped to one paragraph, so it can only ever match the
      // right occurrence, and if it misses (curly apostrophe, a redline
      // splitting the word) the paragraph is still selected — which is the
      // honest answer, not a silent jump somewhere else in the document.
      onLocate: function (rec) {
        var term = String((rec && rec.term) || "");
        var anchor = rec && rec.anchor;
        if (!anchor) {
          if (typeof showToast === "function") {
            showToast("No index anchor for “" + term + "” — rescan to rebuild the index.", "warn");
          }
          return;
        }
        eli.host.runRaw("defined_terms:locate", async function (context) {
          var para = context.document.getBookmarkRangeOrNullObject(anchor);
          para.load("isNullObject");
          await context.sync();
          if (para.isNullObject) {
            throw new Error("That paragraph is gone from the document — rescan.");
          }
          // The needle the scan recorded — the quoted form (“Company”) or the
          // term with its definitional verb (Company means). The BARE term is
          // last, because a preamble says "XYZ Company … (the “Company”)" and
          // searching for "Company" lands on the company name.
          //
          // Word's search treats "^" as an escape even with wildcards off and
          // chokes past 255 chars, so every needle is cleaned and capped.
          var tries = [];
          if (rec && rec.locateNeedle && rec.locateNeedle !== term) tries.push(rec.locateNeedle);
          tries.push(term);
          var clean = function (s) { return String(s).replace(/\^/g, "").substring(0, 200); };
          var target = null, usedBare = false;
          for (var i = 0; i < tries.length && !target; i++) {
            var q = clean(tries[i]);
            if (!q) continue;
            // ignorePunct would erase the very quotes that make the needle
            // distinctive, so punctuation stays literal here.
            var hits = para.search(q, { matchCase: true, ignoreSpace: true });
            hits.load("items");
            await context.sync();
            if (hits.items && hits.items.length) {
              target = hits.items[0];
              usedBare = (i === tries.length - 1 && tries.length > 1);
            }
          }
          var narrowed = !!target;
          if (!target) target = para;
          target.select();
          try { target.scrollIntoView(); } catch (e) { /* older Word builds */ }
          await context.sync();
          return { narrowed: narrowed, usedBare: usedBare };
        }).then(function (r) {
          if (!r || typeof showToast !== "function") return;
          if (!r.narrowed) {
            showToast("Jumped to the paragraph — couldn’t pinpoint “" + term + "” inside it.", "info");
          } else if (r.usedBare) {
            showToast("Landed on “" + term + "” — the definition marker wasn’t found, " +
              "so this may not be the defining occurrence.", "info");
          }
        }).catch(function (err) {
          if (typeof showToast === "function") {
            showToast((err && err.message) || "Could not locate that term.", "warn");
          }
        });
      },
    });
  }

  // ─── [EXTRACT-CHANNEL] ───────────────────────────────────────────────
  // The term list as DATA, for other tools. The panel is one consumer of
  // this; eli_agent is another. Cached against a document signature so a
  // second caller in the same session pays nothing — the OOXML read is the
  // expensive part and the text rarely changes between two calls.
  //
  // opts.paragraphs — caller already holds them (no host round-trip at all)
  // opts.formatting — false to skip the OOXML pass (text-only, ~22ms)
  // TO REMOVE: delete to [/EXTRACT-CHANNEL] and the `extract` registration.
  var _extractCache = null;
  function _sig(paras) {
    var n = paras.length;
    var first = String((paras[0] && paras[0].text) || "").slice(0, 80);
    var last = String((paras[n - 1] && paras[n - 1].text) || "").slice(0, 80);
    var chars = 0;
    for (var i = 0; i < n; i++) chars += String(paras[i].text || "").length;
    return n + ":" + chars + ":" + first + ":" + last;
  }
  function _extract(opts) {
    opts = opts || {};
    var wantFmt = opts.formatting !== false;
    var given = Array.isArray(opts.paragraphs) ? opts.paragraphs : null;
    var read = given
      ? Promise.resolve({ paras: given, runErr: null })
      : _readText().then(function (tp) {
        if (!wantFmt) return { paras: tp, runErr: null };
        return _readRuns()
          .then(function (rp) { return { paras: _attachRuns(tp, rp), runErr: null }; })
          .catch(function (e) { return { paras: tp, runErr: e }; });
      });
    return read.then(function (r) {
      var sig = _sig(r.paras) + "|" + (wantFmt ? "f" : "t");
      if (_extractCache && _extractCache.sig === sig) return _extractCache.result;
      var res = definedTermsScan({
        paragraphs: r.paras,
        toolVersion: (bundle && bundle.releasedAt) || "unknown",
      }, { host: eli.host });
      res._meta.formattingRead = {
        ok: !r.runErr,
        error: r.runErr ? ((r.runErr && r.runErr.message) || "unknown") : null,
      };
      _extractCache = { sig: sig, result: res };
      return res;
    });
  }

  eli.register({
    tile: { app_defined_terms: function () { _scan(); } },
    defined_terms: {
      open: function () { _scan(); },
      extract: _extract,
    },
  });
  // ─── [/EXTRACT-CHANNEL] ──────────────────────────────────────────────
}
